-- Expand only: the running legacy API remains untouched until coordinated cutover.
CREATE TABLE tenant (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 kind varchar(20) NOT NULL CHECK(kind IN ('platform','enterprise')),
 enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX tenant_single_platform ON tenant(kind) WHERE kind='platform';
ALTER TABLE app_user ADD COLUMN tenant_id bigint REFERENCES tenant(id),
 ADD COLUMN status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('invited','active','disabled','deleted'));
UPDATE app_user SET status=CASE WHEN enabled THEN 'active' ELSE 'disabled' END;
ALTER TABLE app_user ALTER COLUMN account TYPE varchar(254);
CREATE INDEX app_user_tenant ON app_user(tenant_id);
ALTER TABLE app_role ADD COLUMN tenant_id bigint REFERENCES tenant(id);
CREATE UNIQUE INDEX app_role_tenant_name ON app_role(tenant_id,lower(btrim(name))) WHERE tenant_id IS NOT NULL;
ALTER TABLE station ADD COLUMN tenant_id bigint REFERENCES tenant(id);
CREATE INDEX station_tenant ON station(tenant_id);
CREATE TABLE tenant_administrator (
 tenant_id bigint PRIMARY KEY REFERENCES tenant(id),user_id bigint NOT NULL UNIQUE REFERENCES app_user(id)
);
CREATE TABLE company_profile (
 tenant_id bigint PRIMARY KEY REFERENCES tenant(id),name varchar(160) NOT NULL CHECK(btrim(name)<>''),
 country varchar(100) NOT NULL,province varchar(120) NOT NULL,city varchar(120) NOT NULL,address varchar(400) NOT NULL,
 latitude numeric(10,7) CHECK(latitude BETWEEN -90 AND 90),longitude numeric(10,7) CHECK(longitude BETWEEN -180 AND 180),
 system_scale varchar(20) CHECK(system_scale IN ('lt100','100to1000','1000to10000','gt10000')),
 postcode varchar(100) NOT NULL,service_description text,registration_no varchar(120),tax_id_ciphertext text,
 contact_name varchar(120) NOT NULL,phone varchar(40) NOT NULL,website varchar(300),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE company_type(code varchar(30) PRIMARY KEY,name_key varchar(100) NOT NULL UNIQUE);
INSERT INTO company_type VALUES('installer','companyType.installer'),('distributor','companyType.distributor'),('service_provider','companyType.serviceProvider'),('operator','companyType.operator');
CREATE TABLE business_scope(code varchar(30) PRIMARY KEY,name_key varchar(100) NOT NULL UNIQUE);
INSERT INTO business_scope VALUES('balcony','scope.balcony'),('residential','scope.residential'),('commercial','scope.commercial'),('utility','scope.utility');
CREATE TABLE tenant_company_type(tenant_id bigint REFERENCES company_profile(tenant_id),type_code varchar(30) REFERENCES company_type(code),PRIMARY KEY(tenant_id,type_code));
CREATE TABLE tenant_business_scope(tenant_id bigint REFERENCES company_profile(tenant_id),scope_code varchar(30) REFERENCES business_scope(code),PRIMARY KEY(tenant_id,scope_code));
CREATE TABLE company_tag(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(60) NOT NULL CHECK(btrim(name)<>''));
CREATE UNIQUE INDEX company_tag_name ON company_tag(lower(btrim(name)));
CREATE TABLE tenant_company_tag(tenant_id bigint REFERENCES company_profile(tenant_id),tag_id bigint REFERENCES company_tag(id) ON DELETE CASCADE,PRIMARY KEY(tenant_id,tag_id));
CREATE TABLE tenant_route(code varchar(120) PRIMARY KEY);
INSERT INTO tenant_route VALUES('overview'),('assets'),('operations'),('maintenance'),('workorders'),('analytics'),('platform'),('settings'),
 ('company.profile'),('company.people'),('company.roles'),('company.grants'),('platform.approvals'),('platform.companies'),('platform.menus'),('platform.packages'),('platform.templates'),('platform.people'),('platform.roles'),('platform.audit');
CREATE TABLE menu (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint REFERENCES menu(id),
 client varchar(10) NOT NULL CHECK(client IN ('web','app')),kind varchar(12) NOT NULL CHECK(kind IN ('directory','page','action')),
 name_key varchar(120) NOT NULL CHECK(btrim(name_key)<>''),route_path varchar(120) REFERENCES tenant_route(code),
 permission_code varchar(100) REFERENCES permission(code),applicable_side varchar(20) CHECK(applicable_side IN ('platform','enterprise','both')),
 sort_order integer NOT NULL DEFAULT 0 CHECK(sort_order>=0),enabled boolean NOT NULL DEFAULT true,remarks text,
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(parent_id IS DISTINCT FROM id),CHECK((parent_id IS NULL)=(applicable_side IS NOT NULL)),
 CHECK((kind='page')=(route_path IS NOT NULL)),CHECK((kind='directory')=(permission_code IS NULL)),UNIQUE(client,name_key)
);
CREATE TABLE permission_package(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(120) NOT NULL CHECK(btrim(name)<>''),enabled boolean NOT NULL DEFAULT true,remarks text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX package_name ON permission_package(lower(btrim(name)));
CREATE TABLE permission_package_menu(package_id bigint REFERENCES permission_package(id) ON DELETE CASCADE,menu_id bigint REFERENCES menu(id),PRIMARY KEY(package_id,menu_id));
CREATE TABLE permission_package_company_type(package_id bigint REFERENCES permission_package(id) ON DELETE CASCADE,type_code varchar(30) REFERENCES company_type(code),PRIMARY KEY(package_id,type_code));
CREATE TABLE role_template(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(120) NOT NULL CHECK(btrim(name)<>''),enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX role_template_name ON role_template(lower(btrim(name)));
CREATE TABLE role_template_permission(template_id bigint REFERENCES role_template(id) ON DELETE CASCADE,permission_code varchar(100) REFERENCES permission(code),client varchar(10) NOT NULL CHECK(client IN ('web','app')),PRIMARY KEY(template_id,permission_code,client));
CREATE TABLE permission_package_template(package_id bigint REFERENCES permission_package(id) ON DELETE CASCADE,template_id bigint REFERENCES role_template(id),PRIMARY KEY(package_id,template_id));
CREATE TABLE tenant_package(tenant_id bigint REFERENCES company_profile(tenant_id),package_id bigint REFERENCES permission_package(id),PRIMARY KEY(tenant_id,package_id));
-- Web/App role configurations are independent even when they use the same API operation code.
ALTER TABLE role_permission ADD COLUMN client varchar(10) NOT NULL DEFAULT 'web' CHECK(client IN ('web','app'));
ALTER TABLE role_permission DROP CONSTRAINT role_permission_pkey;
ALTER TABLE role_permission ADD PRIMARY KEY(role_id,permission_code,client);
ALTER TABLE member_grant ALTER COLUMN role_id DROP NOT NULL;
ALTER TABLE member_grant ADD COLUMN template_id bigint REFERENCES role_template(id),ADD CONSTRAINT member_grant_role_xor CHECK((role_id IS NULL)<>(template_id IS NULL));
CREATE INDEX member_grant_template ON member_grant(template_id) WHERE template_id IS NOT NULL;

CREATE FUNCTION saas_relation_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE owner bigint;other bigint;side text;
BEGIN
 PERFORM pg_advisory_xact_lock(78291002);
 IF TG_TABLE_NAME='tenant_administrator' THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'protected administrator' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'administrator transfer unavailable' USING ERRCODE='23514'; END IF;
  SELECT tenant_id INTO owner FROM app_user WHERE id=NEW.user_id AND status='active';
  IF owner IS DISTINCT FROM NEW.tenant_id THEN RAISE EXCEPTION 'administrator tenant or status' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME IN ('app_user','app_role','station') THEN
  IF TG_OP='DELETE' THEN
   IF TG_TABLE_NAME='app_user' AND EXISTS(SELECT 1 FROM tenant_administrator WHERE user_id=OLD.id) THEN RAISE EXCEPTION 'protected administrator' USING ERRCODE='23514'; END IF;
   RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND OLD.tenant_id IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN RAISE EXCEPTION 'tenant immutable' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='app_user' THEN
   IF NEW.status<>'active' AND EXISTS(SELECT 1 FROM tenant_administrator WHERE user_id=NEW.id) THEN RAISE EXCEPTION 'protected administrator' USING ERRCODE='23514'; END IF;
  END IF;
  IF TG_TABLE_NAME='station' AND NEW.tenant_id IS NOT NULL THEN
   SELECT kind INTO side FROM tenant WHERE id=NEW.tenant_id;
   IF side<>'enterprise' THEN RAISE EXCEPTION 'station requires enterprise' USING ERRCODE='23514'; END IF;
   IF NEW.manager_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM app_user WHERE id=NEW.manager_id AND tenant_id=NEW.tenant_id AND status='active') THEN RAISE EXCEPTION 'station manager tenant or status' USING ERRCODE='23514'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='company_profile' THEN
  IF NOT EXISTS(SELECT 1 FROM tenant WHERE id=NEW.tenant_id AND kind='enterprise') THEN RAISE EXCEPTION 'company requires enterprise' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='member_grant' THEN
  SELECT tenant_id INTO owner FROM app_user WHERE id=NEW.user_id;
  IF owner IS NULL THEN RETURN NEW; END IF; -- expand phase only, NOT an authorization bypass
  IF NEW.role_id IS NOT NULL THEN
   SELECT tenant_id INTO other FROM app_role WHERE id=NEW.role_id;
   IF owner IS DISTINCT FROM other THEN RAISE EXCEPTION 'grant role tenant' USING ERRCODE='23514'; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM tenant_package tp JOIN permission_package_template pt ON pt.package_id=tp.package_id JOIN permission_package p ON p.id=tp.package_id JOIN role_template r ON r.id=pt.template_id WHERE tp.tenant_id=owner AND r.id=NEW.template_id AND p.enabled AND r.enabled) THEN RAISE EXCEPTION 'template unavailable to tenant' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM member_grant_station gs JOIN station s ON s.id=gs.station_id WHERE gs.grant_id=NEW.id AND s.tenant_id IS DISTINCT FROM owner) THEN RAISE EXCEPTION 'grant station tenant' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='member_grant_station' THEN
  SELECT u.tenant_id INTO owner FROM member_grant g JOIN app_user u ON u.id=g.user_id WHERE g.id=NEW.grant_id;
  SELECT tenant_id INTO other FROM station WHERE id=NEW.station_id;
  IF owner IS DISTINCT FROM other THEN RAISE EXCEPTION 'grant station tenant' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='permission_package_menu' THEN
  IF NOT EXISTS(SELECT 1 FROM menu WHERE id=NEW.menu_id AND parent_id IS NULL AND applicable_side IN ('enterprise','both')) THEN RAISE EXCEPTION 'package requires enterprise root' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='tenant_package' THEN
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'replace package through transaction' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' AND NOT EXISTS(SELECT 1 FROM tenant_package WHERE tenant_id=OLD.tenant_id AND package_id<>OLD.package_id) THEN RAISE EXCEPTION 'last tenant package' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE TRIGGER tenant_administrator_guard BEFORE INSERT OR UPDATE OR DELETE ON tenant_administrator FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER app_user_tenant_guard BEFORE INSERT OR UPDATE OR DELETE ON app_user FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER app_role_tenant_guard BEFORE INSERT OR UPDATE ON app_role FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER station_tenant_guard BEFORE INSERT OR UPDATE ON station FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER company_tenant_guard BEFORE INSERT OR UPDATE ON company_profile FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER grant_tenant_guard BEFORE INSERT OR UPDATE ON member_grant FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER grant_station_tenant_guard BEFORE INSERT OR UPDATE ON member_grant_station FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER package_menu_guard BEFORE INSERT OR UPDATE ON permission_package_menu FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();
CREATE TRIGGER tenant_package_guard BEFORE UPDATE OR DELETE ON tenant_package FOR EACH ROW EXECUTE FUNCTION saas_relation_guard();

CREATE FUNCTION saas_menu_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE depth integer;parent_client text;
BEGIN
 PERFORM pg_advisory_xact_lock(78291002);
 IF NEW.parent_id IS NOT NULL THEN
  SELECT client INTO parent_client FROM menu WHERE id=NEW.parent_id;
  IF parent_client IS DISTINCT FROM NEW.client THEN RAISE EXCEPTION 'menu client mismatch' USING ERRCODE='23514'; END IF;
  IF EXISTS(WITH RECURSIVE a AS(SELECT id,parent_id FROM menu WHERE id=NEW.parent_id UNION SELECT m.id,m.parent_id FROM menu m JOIN a ON m.id=a.parent_id) SELECT 1 FROM a WHERE id=NEW.id) THEN RAISE EXCEPTION 'menu cycle' USING ERRCODE='23514'; END IF;
 END IF;
 WITH RECURSIVE ancestors AS(SELECT id,parent_id,1 d FROM menu WHERE id=NEW.parent_id UNION ALL SELECT m.id,m.parent_id,a.d+1 FROM menu m JOIN ancestors a ON m.id=a.parent_id),
 children AS(SELECT NEW.id id,0 d UNION ALL SELECT m.id,c.d+1 FROM menu m JOIN children c ON m.parent_id=c.id WHERE m.id<>NEW.id)
 SELECT 1+coalesce((SELECT max(d) FROM ancestors),0)+coalesce((SELECT max(d) FROM children),0) INTO depth;
 IF depth>4 THEN RAISE EXCEPTION 'menu maximum depth four' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM menu WHERE parent_id=NEW.id AND client<>NEW.client) THEN RAISE EXCEPTION 'menu child client mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.applicable_side='platform' AND EXISTS(SELECT 1 FROM permission_package_menu WHERE menu_id=NEW.id) THEN RAISE EXCEPTION 'package references enterprise root' USING ERRCODE='23514'; END IF;
 IF NEW.parent_id IS NOT NULL AND EXISTS(SELECT 1 FROM permission_package_menu WHERE menu_id=NEW.id) THEN RAISE EXCEPTION 'package root cannot become child' USING ERRCODE='23514'; END IF;
 NEW.updated_at=now();RETURN NEW;
END $$;
CREATE TRIGGER menu_guard BEFORE INSERT OR UPDATE ON menu FOR EACH ROW EXECUTE FUNCTION saas_menu_guard();

CREATE TABLE company_application (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,number varchar(50) NOT NULL UNIQUE,
 email varchar(254) NOT NULL CHECK(email=lower(btrim(email)) AND email<>''),
 name varchar(160) NOT NULL CHECK(btrim(name)<>''),country varchar(100) NOT NULL,province varchar(120) NOT NULL,city varchar(120) NOT NULL,address varchar(400) NOT NULL,
 latitude numeric(10,7) CHECK(latitude BETWEEN -90 AND 90),longitude numeric(10,7) CHECK(longitude BETWEEN -180 AND 180),
 system_scale varchar(20) CHECK(system_scale IN ('lt100','100to1000','1000to10000','gt10000')),postcode varchar(100) NOT NULL,service_description text,registration_no varchar(120),tax_id_ciphertext text,
 contact_name varchar(120) NOT NULL,phone varchar(40) NOT NULL,website varchar(300),
 status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),submitted_at timestamptz NOT NULL DEFAULT now(),tenant_id bigint UNIQUE REFERENCES company_profile(tenant_id),CHECK((status='approved')=(tenant_id IS NOT NULL))
);
CREATE UNIQUE INDEX application_active_email ON company_application(email) WHERE status IN ('pending','approved');
CREATE TABLE application_company_type(application_id bigint REFERENCES company_application(id),type_code varchar(30) REFERENCES company_type(code),PRIMARY KEY(application_id,type_code));
CREATE TABLE application_business_scope(application_id bigint REFERENCES company_application(id),scope_code varchar(30) REFERENCES business_scope(code),PRIMARY KEY(application_id,scope_code));
CREATE TABLE application_event(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id bigint NOT NULL REFERENCES company_application(id),actor_id bigint REFERENCES app_user(id),action varchar(20) NOT NULL CHECK(action IN ('submitted','approved','rejected')),reason text,occurred_at timestamptz NOT NULL DEFAULT now(),CHECK(action<>'rejected' OR length(btrim(reason))>0));
CREATE TABLE email_challenge(id uuid PRIMARY KEY,email varchar(254) NOT NULL CHECK(email=lower(btrim(email))),code_hash varchar(64) NOT NULL,context_hash varchar(64) UNIQUE,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0 AND attempts<=5),created_at timestamptz NOT NULL DEFAULT now(),CHECK(expires_at>created_at));
CREATE TABLE account_activation(id uuid PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),token_hash varchar(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(expires_at>created_at),CHECK(consumed_at IS NULL OR revoked_at IS NULL));
CREATE INDEX activation_user ON account_activation(user_id);
CREATE TABLE mail_delivery(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_key varchar(160) NOT NULL UNIQUE,recipient varchar(254) NOT NULL,language varchar(10) NOT NULL CHECK(language IN ('en','zh-CN')),template varchar(40) NOT NULL,payload_ciphertext text NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed','cancelled')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error varchar(300),created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX mail_delivery_pending ON mail_delivery(next_attempt_at,id) WHERE status IN ('pending','sending');
ALTER TABLE audit_event ADD COLUMN target_tenant_id bigint REFERENCES tenant(id);
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO ems_proto_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO ems_proto_app;
